1007:   function _withdraw(
1008:     address _caller,
1009:     address _receiver,
1010:     address _owner,
1011:     uint256 _assets,
1012:     uint256 _shares
1013:   ) internal virtual override {
1014:     if (_caller != _owner) {
1015:       _spendAllowance(_owner, _caller, _shares);
1016:     }
1017: 
1018:     // If _asset is ERC777, `transfer` can trigger a reentrancy AFTER the transfer happens through the
1019:     // `tokensReceived` hook. On the other hand, the `tokensToSend` hook, that is triggered before the transfer,
1020:     // calls the vault, which is assumed not malicious.
1021:     //
1022:     // Conclusion: we need to do the transfer after the burn so that any reentrancy would happen after the
1023:     // shares are burned and after the assets are transferred, which is a valid state.
1024:     _burn(_owner, _shares);
1025: 
1026:     _yieldVault.withdraw(_assets, address(this), address(this));
1027:     SafeERC20.safeTransfer(IERC20(asset()), _receiver, _assets);
1028: 
1029:     emit Withdraw(_caller, _receiver, _owner, _assets, _shares);
1030:   }

230:     function _withdraw(
231:         address caller,
232:         address receiver,
233:         address owner,
234:         uint256 assets,
235:         uint256 shares
236:     ) internal virtual {
237:         if (caller != owner) {
238:             _spendAllowance(owner, caller, shares);
239:         }
240: 
241:         // If _asset is ERC777, `transfer` can trigger a reentrancy AFTER the transfer happens through the
242:         // `tokensReceived` hook. On the other hand, the `tokensToSend` hook, that is triggered before the transfer,
243:         // calls the vault, which is assumed not malicious.
244:         //
245:         // Conclusion: we need to do the transfer after the burn so that any reentrancy would happen after the
246:         // shares are burned and after the assets are transferred, which is a valid state.
247:         _burn(owner, shares);
248:         SafeERC20.safeTransfer(_asset, receiver, assets);
249: 
250:         emit Withdraw(caller, receiver, owner, assets, shares);
251:     }

509:   function withdraw(
510:     uint256 _assets,
511:     address _receiver,
512:     address _owner
513:   ) public virtual override returns (uint256) {
514:     if (_assets > maxWithdraw(_owner))
515:       revert WithdrawMoreThanMax(_owner, _assets, maxWithdraw(_owner));
516: 
517:     uint256 _shares = _convertToShares(_assets, Math.Rounding.Up);
518:     _withdraw(msg.sender, _receiver, _owner, _assets, _shares);
519: 
520:     return _shares;
521:   }

524:   function redeem(
525:     uint256 _shares,
526:     address _receiver,
527:     address _owner
528:   ) public virtual override returns (uint256) {
529:     if (_shares > maxRedeem(_owner)) revert RedeemMoreThanMax(_owner, _shares, maxRedeem(_owner));
530: 
531:     uint256 _assets = _convertToAssets(_shares, Math.Rounding.Down);
532:     _withdraw(msg.sender, _receiver, _owner, _assets, _shares);
533: 
534:     return _assets;
535:   }

