864:   function _convertToShares(
865:     uint256 _assets,
866:     Math.Rounding _rounding
867:   ) internal view virtual override returns (uint256) {
868:     uint256 _exchangeRate = _currentExchangeRate();
869: 
870:     return
871:       (_assets == 0 || _exchangeRate == 0)
872:         ? _assets
873:         : _assets.mulDiv(_assetUnit, _exchangeRate, _rounding);
874:   }

882:   function _convertToAssets(
883:     uint256 _shares,
884:     Math.Rounding _rounding
885:   ) internal view virtual override returns (uint256) {
886:     return _convertToAssets(_shares, _currentExchangeRate(), _rounding);
887:   }

896:   function _convertToAssets(
897:     uint256 _shares,
898:     uint256 _exchangeRate,
899:     Math.Rounding _rounding
900:   ) internal view returns (uint256) {
901:     return
902:       (_shares == 0 || _exchangeRate == 0)
903:         ? _shares
904:         : _shares.mulDiv(_exchangeRate, _assetUnit, _rounding);
