128:     function maxRedeem(address owner) public view virtual override returns (uint256) {
129:         return balanceOf(owner);
130:     }

123:     function maxWithdraw(address owner) public view virtual override returns (uint256) {
124:         return _convertToAssets(balanceOf(owner), Math.Rounding.Down);
125:     }

515:   function _transferBalance(address _vault, address _from, address _to, uint96 _amount) internal {
516:     if (_from == _to) {
517:       return;
518:     }
519: 
520:     // If we are transferring tokens from a delegated account to an undelegated account
521:     address _fromDelegate = _delegateOf(_vault, _from);
522:     address _toDelegate = _delegateOf(_vault, _to);
523:     if (_from != address(0)) {
524:       bool _isFromDelegate = _fromDelegate == _from;
525: 
526:       _decreaseBalances(_vault, _from, _amount, _isFromDelegate ? _amount : 0);
527: 
528:       // If the user is not delegating to themself, decrease the delegate's delegateBalance
529:       // If the user is delegating to the sponsorship address, don't adjust the delegateBalance
530:       if (!_isFromDelegate && _fromDelegate != SPONSORSHIP_ADDRESS) {
531:         _decreaseBalances(_vault, _fromDelegate, 0, _amount);
532:       }
533: 
534:       // Burn balance if we're transferring to address(0)
535:       // Burn delegateBalance if we're transferring to address(0) and burning from an address that is not delegating to the sponsorship address
536:       // Burn delegateBalance if we're transferring to an address delegating to the sponsorship address from an address that isn't delegating to the sponsorship address
537:       if (
538:         _to == address(0) ||
539:         (_toDelegate == SPONSORSHIP_ADDRESS && _fromDelegate != SPONSORSHIP_ADDRESS)
540:       ) {
541:         // If the user is delegating to the sponsorship address, don't adjust the total supply delegateBalance
542:         _decreaseTotalSupplyBalances(
543:           _vault,
544:           _to == address(0) ? _amount : 0,
545:           (_to == address(0) && _fromDelegate != SPONSORSHIP_ADDRESS) ||
546:             (_toDelegate == SPONSORSHIP_ADDRESS && _fromDelegate != SPONSORSHIP_ADDRESS)
547:             ? _amount
548:             : 0
549:         );
550:       }
551:     }
552: 
553:     // If we are transferring tokens to an address other than address(0)
554:     if (_to != address(0)) {
555:       bool _isToDelegate = _toDelegate == _to;
556: 
557:       // If the user is delegating to themself, increase their delegateBalance
558:       _increaseBalances(_vault, _to, _amount, _isToDelegate ? _amount : 0);
559: 
560:       // Otherwise, increase their delegates delegateBalance if it is not the sponsorship address
561:       if (!_isToDelegate && _toDelegate != SPONSORSHIP_ADDRESS) {
562:         _increaseBalances(_vault, _toDelegate, 0, _amount);
563:       }
564: 
565:       // Mint balance if we're transferring from address(0)
566:       // Mint delegateBalance if we're transferring from address(0) and to an address not delegating to the sponsorship address
567:       // Mint delegateBalance if we're transferring from an address delegating to the sponsorship address to an address that isn't delegating to the sponsorship address
568:       if (
569:         _from == address(0) ||
570:         (_fromDelegate == SPONSORSHIP_ADDRESS && _toDelegate != SPONSORSHIP_ADDRESS)
571:       ) {
572:         _increaseTotalSupplyBalances(
573:           _vault,
574:           _from == address(0) ? _amount : 0,
575:           (_from == address(0) && _toDelegate != SPONSORSHIP_ADDRESS) ||
576:             (_fromDelegate == SPONSORSHIP_ADDRESS && _toDelegate != SPONSORSHIP_ADDRESS)
577:             ? _amount
578:             : 0
579:         );
580:       }
581:     }
582:   }
